// Shared source, embedded into each workflow by the exporter. No secrets in items.
const SB_URL='https://abujjbkbbiumxrokozph.supabase.co';
const N8N_URL='https://n8n.higher.boutique';
// 03/11 (Wah) : la curation est une MISSION remuneree. Meme somme que dans B.
const GAIN_CURATEUR='20 €';
// 04/11 : la zone d'impression REELLE de Printful fait 1800x2400 (150 dpi). Un concept
// 1024x1536 upscale x2 donne 2048x3072 : on REDUIT vers la cible au lieu d'agrandir,
// donc plus net. x3 et x4 rendaient des PNG que `compose-artwork` ne pouvait plus
// decoder — `not having enough compute resources` — sans rien apporter a l'impression.
const UPSCALE=2;
const uuid=value=>/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(String(value||''));
const sbHeaders={apikey:$env.SB_KEY,'Content-Type':'application/json'};
const pfHeaders={Authorization:'Bearer '+$env.PRINTFUL_TOKEN,'X-PF-Store-Id':String($env.PF_STORE_ID),'Content-Type':'application/json'};
const request=async options=>{
  let response;
  try{response=await this.helpers.httpRequest({...options,json:options.json!==false,
    returnFullResponse:true,ignoreHttpStatusErrors:true,timeout:options.timeout||30000});}
  catch{throw new Error('transport_'+String(options.method||'GET').toLowerCase());}
  if(response.statusCode>=400){
    // 03/11 : un fournisseur qui refuse DIT pourquoi. Sans ce detail, toute panne
    // externe se resume a `http_402` et le pipeline est aveugle. 110 caracteres au
    // plus : `streetwear_fail` tronque le code a 160.
    let detail='';
    try{const b=response.body;
      detail=String(typeof b==='string'?b:(b&&b.error&&b.error.message)||(b&&b.detail)||(b&&b.message)||JSON.stringify(b)||'').replace(/\s+/g,' ').trim().slice(0,110);}
    catch{ /* un corps illisible ne vaut pas une panne de plus */ }
    const error=new Error('http_'+response.statusCode+(detail?' '+detail:''));error.status=response.statusCode;throw error;}
  return response.body;
};
const rpc=(name,body={})=>request({method:'POST',url:SB_URL+'/rest/v1/rpc/'+name,headers:sbHeaders,body});
const db=(path,method='GET',body,extra={})=>request({method,url:SB_URL+'/rest/v1/'+path,headers:{...sbHeaders,...extra},...(body!==undefined?{body}:{})});
const serviceAuth=async headers=>{
  const key=headers?.apikey||String(headers?.authorization||'').replace(/^Bearer\s+/i,'');
  if(!key)return false;
  const backendHeaders={apikey:key,'Content-Type':'application/json',...(!key.startsWith('sb_')?{Authorization:'Bearer '+key}:{})};
  try{return await request({method:'POST',url:SB_URL+'/rest/v1/rpc/streetwear_service_ready',headers:backendHeaders,body:{},timeout:5000})===true;}
  catch{return false;}
};
const failResult=(reason,http_status=400)=>[{json:{ok:false,reason,http_status}}];
const ticketResult=ticket=>[{json:{...ticket,http_status:ticket.ok?202:(ticket.reason==='not_found'?404:200)}}];
const checkpoint=(ticket,data,wait=false)=>rpc('streetwear_checkpoint',{p_cloth:ticket.cloth.id,p_stage:ticket.stage,p_token:ticket.token,p_data:data,p_wait:wait});
const complete=(ticket,result={})=>rpc('streetwear_complete',{p_cloth:ticket.cloth.id,p_stage:ticket.stage,p_token:ticket.token,p_result:result});
const fail=(ticket,code,retry=false)=>rpc('streetwear_fail',{p_cloth:ticket.cloth.id,p_stage:ticket.stage,p_token:ticket.token,p_code:String(code).slice(0,160),p_retry:retry});
const callFlow=(path,body)=>request({method:'POST',url:N8N_URL+'/webhook/'+path,headers:sbHeaders,body,timeout:10000});
const refreshAsset=body=>request({method:'POST',url:SB_URL+'/functions/v1/streetwear-assets',headers:sbHeaders,body});
const tg=(method,body)=>request({method:'POST',url:'https://api.telegram.org/bot'+$env.TG_TOKEN+'/'+method,body});
const escapeHtml=value=>String(value||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const gainCurateur=()=>GAIN_CURATEUR;

// SHA-256 only derives a separate provider webhook token; it never signs artwork.
function sha256(ascii){
  const rightRotate=(value,amount)=>(value>>>amount)|(value<<(32-amount));
  const maxWord=2**32,words=[],bitLength=ascii.length*8;
  let hash=[],constants=[],primeCounter=0;
  const composite={};
  for(let candidate=2;primeCounter<64;candidate++)if(!composite[candidate]){
    for(let i=0;i<313;i+=candidate)composite[i]=candidate;
    hash[primeCounter]=(Math.sqrt(candidate)*maxWord)|0;
    constants[primeCounter++]=(Math.cbrt(candidate)*maxWord)|0;
  }
  ascii+='\x80';while(ascii.length%64!==56)ascii+='\x00';
  for(let i=0;i<ascii.length;i++)words[i>>2]|=ascii.charCodeAt(i)<<(24-(i%4)*8);
  words.push((bitLength/maxWord)|0,bitLength);
  hash=hash.slice(0,8);
  for(let j=0;j<words.length;){
    const w=words.slice(j,j+=16),oldHash=hash.slice();
    for(let i=0;i<64;i++){
      const w15=w[i-15],w2=w[i-2],a=hash[0],e=hash[4];
      const temp1=hash[7]+(rightRotate(e,6)^rightRotate(e,11)^rightRotate(e,25))+((e&hash[5])^((~e)&hash[6]))+constants[i]+
        (w[i]=i<16?w[i]:(w[i-16]+(rightRotate(w15,7)^rightRotate(w15,18)^(w15>>>3))+w[i-7]+(rightRotate(w2,17)^rightRotate(w2,19)^(w2>>>10)))|0);
      const temp2=(rightRotate(a,2)^rightRotate(a,13)^rightRotate(a,22))+((a&hash[1])^(a&hash[2])^(hash[1]&hash[2]));
      hash=[(temp1+temp2)|0,a,hash[1],hash[2],(hash[3]+temp1)|0,hash[4],hash[5],hash[6]];
    }
    for(let i=0;i<8;i++)hash[i]=(hash[i]+oldHash[i])|0;
  }
  return hash.map(value=>(value>>>0).toString(16).padStart(8,'0')).join('');
}

const ticket=$input.first().json;
if(!ticket.ok)return [];
// 05/11 : l'annonce d'une piece bloquee. Un essai le dit, pour qu'on ne cherche pas un
// acheteur qui n'existe pas. Les deux boutons sont les seuls chemins hors d'`error_locked`.
if(ticket.route==='alert'){
  let envoyees=0;
  for(const a of (ticket.alert||[])){
    const essai=a.test?' <i>(essai)</i>':'';
    const texte='\u26a0\ufe0f <b>BLOCKED</b>'+essai+'\n'+
      '<b>'+escapeHtml(String(a.name||''))+'</b> stopped at <b>'+escapeHtml(String(a.stage||''))+'</b>\n'+
      '<code>'+escapeHtml(String(a.last_error||'unknown'))+'</code>\n\n'+
      (a.price?'Paid '+escapeHtml(String(a.price))+' \u20ac. ':'')+
      'RETRY runs that step again and pays for it. REFUND only records the decision.';
    try{
      await tg('sendMessage',{chat_id:$env.TG_CHAT,text:texte,parse_mode:'HTML',
        reply_markup:{inline_keyboard:[[{text:'RETRY',callback_data:'retry:'+a.cloth_id},
          {text:'REFUND',callback_data:'refund:'+a.cloth_id}]]}});
      envoyees++;
    }catch{ /* le marqueur est pose : le tic suivant ne repetera pas */ }
  }
  return [{json:{ok:true,route:'alert',envoyees}}];
}
// Reprendre une piece bloquee, ou noter qu'elle doit etre remboursee.
if(ticket.route==='retry'||ticket.route==='refund'||ticket.route==='refundok'){
  let note='';
  if(ticket.route==='refund'){
    // Un seul tap ne touche pas l'argent : on redemande.
    try{await tg('answerCallbackQuery',{callback_query_id:ticket.callback_id,text:'Confirm below.'});}catch{}
    try{await tg('editMessageReplyMarkup',{chat_id:$env.TG_CHAT,message_id:ticket.message_id,
      reply_markup:{inline_keyboard:[[{text:'REFUND \u2014 CONFIRM',callback_data:'refundok:'+ticket.cloth_id},
        {text:'RETRY',callback_data:'retry:'+ticket.cloth_id}]]}});}catch{}
    return [{json:{ok:true,route:'refund',cloth_id:ticket.cloth_id}}];
  }
  const r=await rpc(ticket.route==='retry'?'streetwear_unlock':'streetwear_refund_mark',{p_cloth:ticket.cloth_id});
  if(ticket.callback_id)try{await tg('answerCallbackQuery',{callback_query_id:ticket.callback_id,
    text:r&&r.ok?(ticket.route==='retry'?'Back in the queue\u2026':'Refund recorded.'):String((r&&r.reason)||'refused')});}catch{}
  if(r&&r.ok&&ticket.route==='retry')note='\u21ba RETRIED \u2014 back in the queue at '+escapeHtml(String(r.stage||''));
  else if(r&&r.ok)note='\u20ac REFUND RECORDED \u2014 Stripe payment '+escapeHtml(String(r.intent||'unknown'))+
    '\nNothing has been refunded yet: do it in Stripe.';
  else note='\u2716 REFUSED \u2014 '+escapeHtml(String((r&&r.reason)||'unknown'));
  if(ticket.message_id)try{await tg('editMessageText',{chat_id:$env.TG_CHAT,message_id:ticket.message_id,
    text:note,parse_mode:'HTML'});}catch{}
  return [{json:{ok:!!(r&&r.ok),route:ticket.route,cloth_id:ticket.cloth_id}}];
}
// Le controle qualite repart vers D, qui repondra lui-meme au bouton.
if(ticket.route==='ship'||ticket.route==='hold'){
  try{await callFlow('streetwear-printful',{cloth_id:ticket.cloth_id,decision:ticket.route,
    callback_id:ticket.callback_id,message_id:ticket.message_id});}catch{ /* durable Printful job */ }
  return [{json:{ok:true,route:ticket.route}}];
}
if(ticket.callback_id)try{await tg('answerCallbackQuery',{callback_query_id:ticket.callback_id,text:ticket.route==='regen'?'Regenerating…':'Processing your choice…'});}catch{}
if(ticket.route==='regen'){
  try{await callFlow('streetwear-generate',{cloth_id:ticket.cloth_id});}catch{ /* queued in DB */ }
  return [{json:{ok:true,route:'regen'}}];
}
// 04/11 (Wah) : le choix est pris — les sept boutons disparaissent, et l'image retenue le
// dit. Un second clic etait deja refuse par la base ; desormais il n'y a plus rien a
// cliquer, et le curateur voit que sa mission est partie.
{
  const picks=ticket.pick_messages||{};
  const choisi=String((ticket.concept&&ticket.concept.position)||'');
  for(const position of Object.keys(picks)){
    try{
      if(position===choisi)await tg('editMessageCaption',{chat_id:$env.TG_CHAT,message_id:picks[position],
        caption:'— '+position+' of 7 — ✓ PICKED'});
      else await tg('editMessageReplyMarkup',{chat_id:$env.TG_CHAT,message_id:picks[position],
        reply_markup:{inline_keyboard:[]}});
    }catch{ /* un message efface ne coute pas la curation */ }
  }
}
const cloth=ticket.cloth,saved=ticket.job.data||{};
let retryable=!!saved.prediction_id||!!saved.upscaled_url;
try{
  let source=saved.upscaled_url;
  if(!source){
    let prediction;
    if(saved.prediction_id){
      prediction=await request({url:'https://api.replicate.com/v1/predictions/'+encodeURIComponent(saved.prediction_id),
        headers:{Authorization:'Bearer '+$env.REPLICATE_KEY}});
    }else{
      if(saved.prediction_request_started)throw new Error('prediction_outcome_unknown');
      if(!$env.REPLICATE_KEY||!$env.REPLICATE_VERSION)throw new Error('upscale_configuration');
      const signed=await refreshAsset({cloth_id:cloth.id,concept_id:ticket.concept.id});
      await checkpoint(ticket,{prediction_request_started:true});
      prediction=await request({method:'POST',url:'https://api.replicate.com/v1/predictions',
        headers:{Authorization:'Bearer '+$env.REPLICATE_KEY,'Content-Type':'application/json',Prefer:'wait=5','Cancel-After':'10m'},
        body:{version:$env.REPLICATE_VERSION,input:{image:signed.url,scale:UPSCALE}},timeout:20000});
      if(!prediction.id)throw new Error('prediction_missing_id');
      await checkpoint(ticket,{prediction_id:prediction.id});retryable=true;
    }
    if(['failed','canceled'].includes(prediction.status)){retryable=false;throw new Error('prediction_'+prediction.status);}
    if(prediction.status!=='succeeded'){
      await checkpoint(ticket,{prediction_id:prediction.id},true);
      return [{json:{ok:true,pending:true,cloth_id:cloth.id}}];
    }
    source=Array.isArray(prediction.output)?prediction.output[0]:prediction.output;
    // 04/11 : Replicate PURGE ses sorties au bout d'une heure — une prediction reussie
    // dont personne n'a repris le fichier rend `output: null`. Le dire, plutot que de
    // laisser croire a un format inattendu.
    if(source===null||source===undefined)throw new Error('upscale_expired');
    if(typeof source!=='string'||!/^https:\/\//.test(source))throw new Error('upscale_output');
    await checkpoint(ticket,{upscaled_url:source});
  }
  const composed=await request({method:'POST',url:SB_URL+'/functions/v1/compose-artwork',headers:sbHeaders,
    body:{cloth_id:cloth.id,source_url:source},timeout:200000});
  if(!composed.print_url||!composed.final_url||!composed.storage_path)throw new Error('compose_output');
  if(!await complete(ticket,composed))throw new Error('curation_lease');
  // 03/11 (Wah) : la mission se CLOT sur ce qu'elle rapporte, et MONTRE l'oeuvre —
  // signature comprise. C'est le seul endroit ou une piece d'essai se verifie des l'oeil.
  // Un echec d'envoi ne defait pas une curation deja enregistree.
  const legende='✓ <b>'+escapeHtml(String(composed.name||cloth.name||''))+'</b> is encoded.\n'+
    'You picked artwork '+String(ticket.concept&&ticket.concept.position||'')+' of 7.\n\n'+
    '<b>You earned '+gainCurateur()+'</b> — mission complete.';
  try{
    if(composed.preview_url)await tg('sendPhoto',{chat_id:$env.TG_CHAT,photo:composed.preview_url,caption:legende,parse_mode:'HTML'});
    else await tg('sendMessage',{chat_id:$env.TG_CHAT,text:legende,parse_mode:'HTML'});
  }catch{ /* la piece est deja curatee */ }
  try{await callFlow('streetwear-printful',{cloth_id:cloth.id});}catch{ /* durable Printful job */ }
  return [{json:{ok:true,cloth_id:cloth.id}}];
}catch(error){
  const code=String(error.message||'curation_failed');
  await fail(ticket,code,retryable);
  throw new Error('Streetwear curation failed: '+code);
}

