const input=$input.first().json,body=input.body||{};
const internal=await serviceAuth(input.headers);
const expected=$env.TG_WEBHOOK_SECRET||sha256('totehm-telegram-webhook-v1:'+$env.TG_TOKEN);
const telegram=!!$env.TG_TOKEN&&input.headers?.['x-telegram-bot-api-secret-token']===expected;
if(!internal&&!telegram)return failResult('unauthorized',401);
if(internal&&uuid(body.resume_cloth_id)){
  const cloth=(await db('totehm_clothes?id=eq.'+body.resume_cloth_id+'&select=selected_concept_id'))[0];
  if(!uuid(cloth?.selected_concept_id))return failResult('not_selected',200);
  return ticketResult(await rpc('streetwear_claim',{p_cloth:body.resume_cloth_id,p_stage:'curation',p_concept:cloth.selected_concept_id}));
}
// 05/11 (Wah) : une piece payee bloquee en `error_locked` n'avait aucune suite. Le tic la
// repere et nous l'envoie ici : C est le poste Telegram du streetwear, lui seul a le bot.
if(internal&&Array.isArray(body.alert)){
  const liste=body.alert.filter(a=>a&&uuid(a.cloth_id)).slice(0,10);
  if(!liste.length)return failResult('empty_alert',200);
  return [{json:{ok:true,http_status:202,route:'alert',alert:liste}}];
}
const cb=body.callback_query;
if(!cb||!/^(pick|regen|ship|hold|retry|refund|refundok):/.test(String(cb.data||'')))return failResult('ignored',200);
const [action,id]=String(cb.data).split(':');
const chat=String(cb.message?.chat?.id||''),who=String(cb.from?.id||'');
const allowed=String($env.TG_ADMIN_IDS||'').split(',').map(x=>x.trim()).filter(Boolean);
if(!uuid(id)||chat!==String($env.TG_CHAT)||!who||
  (Number($env.TG_CHAT)>0?who!==String($env.TG_CHAT):!allowed.includes(who)))return failResult('curator_only',403);
// 04/11 : Telegram n'a qu'UN point d'entree — tous les boutons arrivent ici. C est donc
// le routeur : le controle qualite d'une commande deja creee repart vers D.
// La sortie de secours : reprendre, ou noter un remboursement. Le nom du geste dit tout —
// `refund` DEMANDE, `refundok` NOTE. L'argent ne part jamais d'un seul tap.
if(action==='retry'||action==='refund'||action==='refundok')
  return [{json:{ok:true,http_status:200,route:action,cloth_id:id,callback_id:cb.id,
    message_id:(cb.message&&cb.message.message_id)||null}}];
if(action==='ship'||action==='hold')
  return [{json:{ok:true,http_status:200,route:action,cloth_id:id,callback_id:cb.id,
    message_id:(cb.message&&cb.message.message_id)||null}}];
let clothId=id,pickedBatch=null;
if(action==='pick'){
  const concept=(await db('cloth_concepts?id=eq.'+id+'&select=cloth_id,batch_id'))[0];
  if(!concept)return failResult('not_found',404);clothId=concept.cloth_id;pickedBatch=concept.batch_id;
}
// 04/11 (Wah) : « j'ai rappuye sur Prendre la 1 et rien ne se passe ». Le garde-fou
// anti-rejeu comparait le message du bouton a UN `curation_message_id`. Depuis que les
// sept concepts partent chacun dans LEUR message (03/11, pour lier le numero a l'image),
// ce champ ne designe plus rien : tout bouton etait rejete en `stale_button`, et la
// curation n'etait plus joignable que par un rattrapage manuel. On verifie ce qu'il faut
// vraiment verifier — que le concept choisi appartient au LOT COURANT de la piece.
const inbox=(await db('streetwear_jobs?cloth_id=eq.'+clothId+'&stage=eq.notify&select=state,data'))[0];
if(inbox?.state!=='done')return failResult('stale_button',200);
if(action==='pick'){
  const lot=(await db('totehm_clothes?id=eq.'+clothId+'&select=generation_batch'))[0];
  if(!lot||!pickedBatch||String(pickedBatch)!==String(lot.generation_batch))return failResult('stale_batch',200);
}
